1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12	)
13	
14	// Restore loads a backup artifact produced by Store.Backup from backupDir and
15	// installs a ready-to-open store into targetDir, returning it already open.
16	// The restored directory, once reopened, is byte-for-byte the complete
17	// committed state at the export watermark: a full replay from it yields the
18	// same terminal state the backup captured, and the cumulative snapshot count
19	// is preserved exactly.
20	//
21	// The artifact is validated as one whole before anything is installed: a
22	// missing segment, a truncated segment, a checksum mismatch, an unknown format
23	// version or a manifest that disagrees with the files rejects the entire
24	// backup with an error wrapping fs.ErrInvalid, and no target is created.
25	//
26	// Installation is all-or-nothing: the new store is fully built and synced in a
27	// temporary sibling directory and only then renamed onto targetDir. A process
28	// killed at any instant leaves either the previous target or one complete
29	// store; a half-built temporary directory is swept by the next Restore or the
30	// next Open of the related directory.
31	//
32	// A backup path that does not exist or is not a directory is rejected with an
33	// error wrapping fs.ErrInvalid. A target path that already exists and is not
34	// empty (including a regular file) is rejected the same way.
35	func Restore(backupDir, targetDir string) (*Store, error) {
36		if backupDir == "" || targetDir == "" {
37			return nil, errBadBackup
38		}
39	
40		// The artifact itself must be an existing directory whose only entries are
41		// the manifest and the segments it names.
42		binfo, err := os.Stat(backupDir)
43		if err != nil {
44			return nil, errBadBackup
45		}
46		if !binfo.IsDir() {
47			return nil, errBadBackup
48		}
49	
50		manifest, err := loadBackupManifest(backupDir)
51		if err != nil {
52			// Content defects already wrap fs.ErrInvalid; an underlying read
53			// failure passes through unchanged.
54			return nil, err
55		}
56		if err := verifyBackupFileSet(backupDir, manifest.segments); err != nil {
57			return nil, err
58		}
59	
60		// The target must be absent or an empty directory.
61		if err := checkRestoreTarget(targetDir); err != nil {
62			return nil, err
63		}
64	
65		// Build the complete store in a temporary sibling so a kill never exposes
66		// a half-installed target. The sibling lives next to the target so the
67		// final rename is atomic on one filesystem.
68		parent := filepath.Dir(targetDir)
69		if err := os.MkdirAll(parent, 0o700); err != nil {
70			return nil, err
71		}
72		stage, err := os.MkdirTemp(parent, filepath.Base(targetDir)+".restore-*")
73		if err != nil {
74			return nil, err
75		}
76		installed := false
77		defer func() {
78			if !installed {
79				_ = os.RemoveAll(stage)
80			}
81		}()
82	
83		if err := buildRestoredStore(stage, backupDir, manifest); err != nil {
84			// Artifact validation failures already wrap fs.ErrInvalid; a genuine
85			// write failure is reported as-is rather than mislabeled invalid.
86			return nil, err
87		}
88	
89		if err := installRestoreTarget(stage, targetDir); err != nil {
90			return nil, err
91		}
92		installed = true
93	
94		return Open(targetDir)
95	}
96	
97	// checkRestoreTarget accepts an absent path or an existing empty directory;
98	// anything else (a regular file, symlink, or non-empty directory) is invalid.
99	func checkRestoreTarget(target string) error {
100		info, err := os.Stat(target)
101		if err != nil {
102			if errors.Is(err, os.ErrNotExist) {
103				return nil
104			}
105			return err
106		}
107		if !info.IsDir() {
108			return errBadBackup
109		}
110		entries, err := os.ReadDir(target)
111		if err != nil {
112			return err
113		}
114		if len(entries) != 0 {
115			return errBadBackup
116		}
117		return nil
118	}
119	
120	// verifyBackupFileSet rejects any entry besides the manifest and exactly the
121	// dense segment set the manifest names, and rejects gaps or extras.
122	func verifyBackupFileSet(backupDir string, segs []manifestSegment) error {
123		entries, err := os.ReadDir(backupDir)
124		if err != nil {
125			return err
126		}
127		want := make(map[uint32]bool, len(segs))
128		for _, s := range segs {
129			if s.index != uint32(len(want)) {
130				return errBadBackup // dense, ordered 0..n-1
131			}
132			want[s.index] = true
133		}
134		got := make(map[uint32]bool, len(segs))
135		for _, e := range entries {
136			if e.IsDir() {
137				return errBadBackup // no staging or foreign directory in a valid artifact
138			}
139			name := e.Name()
140			if name == backupManifest || name == backupManifestTmp {
141				if name == backupManifestTmp {
142					return errBadBackup // an unfinished manifest means an unfinished export
143				}
144				continue
145			}
146			idx, ok := parseSegmentIndex(name)
147			if !ok {
148				return errBadBackup // foreign file
149			}
150			if !want[idx] {
151				return errBadBackup // extra segment
152			}
153			if got[idx] {
154				return errBadBackup
155			}
156			got[idx] = true
157		}
158		if len(got) != len(want) {
159			return errBadBackup // a named segment is missing
160		}
161		return nil
162	}
163	
164	// readFull reads exactly len(buf) bytes from r; a short read (a truncated
165	// artifact) is reported as errBadBackup rather than io.ErrUnexpectedEOF,
166	// while any other read failure passes through.
167	func readFull(r io.Reader, buf []byte) error {
168		if _, err := io.ReadFull(r, buf); err != nil {
169			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
170				return errBadBackup
171			}
172			return err
173		}
174		return nil
175	}
176	
177	// loadBackupManifest reads and fully validates manifest.dat.
178	func loadBackupManifest(backupDir string) (manifestInfo, error) {
179		var zero manifestInfo
180		f, err := os.Open(filepath.Join(backupDir, backupManifest))
181		if err != nil {
182			// A missing manifest means the export never reached its commit point:
183			// the artifact is incomplete, not a transient I/O failure.
184			if errors.Is(err, os.ErrNotExist) {
185				return zero, errBadBackup
186			}
187			return zero, err
188		}
189		defer f.Close()
190	
191		r := bufio.NewReader(f)
192		head := make([]byte, backupManifestSize)
193		if err := readFull(r, head); err != nil {
194			return zero, err
195		}
196		h := crc32.NewIEEE()
197		h.Write(head)
198	
199		magic := binary.LittleEndian.Uint32(head[0:4])
200		version := binary.LittleEndian.Uint32(head[4:8])
201		if magic != backupMagic || version != backupVersion {
202			return zero, errBadBackup
203		}
204		info := manifestInfo{
205			watermark: binary.LittleEndian.Uint64(head[8:16]),
206			snaps:     binary.LittleEndian.Uint64(head[16:24]),
207			total:     binary.LittleEndian.Uint64(head[24:32]),
208		}
209		n := binary.LittleEndian.Uint32(head[32:36])
210		// Every segment carries at least one entry, so the segment count never
211		// exceeds the entry total; an empty artifact has n == 0 and total == 0.
212		// The absolute cap only guards the pre-allocation against a forged count;
213		// the record loop rejects an artifact that does not actually contain them.
214		if uint64(n) > info.total || n > backupMaxSegments {
215			return zero, errBadBackup
216		}
217	
218		rec := make([]byte, backupSegRecSize)
219		var cumulative uint64
220		info.segments = make([]manifestSegment, 0, n)
221		for i := uint32(0); i < n; i++ {
222			if err := readFull(r, rec); err != nil {
223				return zero, err
224			}
225			h.Write(rec)
226			s := manifestSegment{
227				index:      binary.LittleEndian.Uint32(rec[0:4]),
228				count:      binary.LittleEndian.Uint32(rec[4:8]),
229				cumulative: binary.LittleEndian.Uint64(rec[8:16]),
230				crc:        binary.LittleEndian.Uint32(rec[16:20]),
231			}
232			if s.index != i {
233				return zero, errBadBackup
234			}
235			cumulative += uint64(s.count)
236			if s.cumulative != cumulative || s.count == 0 {
237				return zero, errBadBackup
238			}
239			info.segments = append(info.segments, s)
240		}
241		if cumulative != info.total {
242			return zero, errBadBackup
243		}
244	
245		var crcb [crcSize]byte
246		if err := readFull(r, crcb[:]); err != nil {
247			return zero, err
248		}
249		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
250			return zero, errBadBackup
251		}
252		if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
253			return zero, errBadBackup // trailing bytes, or an underlying read error
254		}
255		return info, nil
256	}
257	
258	// buildRestoredStore streams every named segment into a fresh wal.log in the
259	// staging directory, validating each segment as it reads. The result is a WAL
260	// whose full replay reproduces the exported terminal state (one terminal
261	// frame per key, the same shape a compaction writes), followed by the snapshot
262	// count meta. Nothing is installed until this whole step succeeds.
263	func buildRestoredStore(stage, backupDir string, info manifestInfo) error {
264		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
265		if err != nil {
266			return err
267		}
268		fail := func(err error) error {
269			wf.Close()
270			return err
271		}
272		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
273	
274		var seen uint64
275		var lastKey string
276		haveKeys := false
277	
278		for _, seg := range info.segments {
279			f, err := os.Open(filepath.Join(backupDir, segmentName(seg.index)))
280			if err != nil {
281				return fail(err)
282			}
283			r := bufio.NewReader(f)
284			hdr := make([]byte, backupSegHeaderSize)
285			if err := readFull(r, hdr); err != nil {
286				f.Close()
287				return fail(err)
288			}
289			h := crc32.NewIEEE()
290			h.Write(hdr)
291	
292			magic := binary.LittleEndian.Uint32(hdr[0:4])
293			version := binary.LittleEndian.Uint32(hdr[4:8])
294			watermark := binary.LittleEndian.Uint64(hdr[8:16])
295			snaps := binary.LittleEndian.Uint64(hdr[16:24])
296			index := binary.LittleEndian.Uint32(hdr[24:28])
297			count := binary.LittleEndian.Uint32(hdr[28:32])
298			cumulative := binary.LittleEndian.Uint64(hdr[32:40])
299			if magic != backupMagic || version != backupVersion ||
300				watermark != info.watermark || snaps != info.snaps ||
301				index != seg.index || count != seg.count || cumulative != seg.cumulative {
302				f.Close()
303				return fail(errBadBackup)
304			}
305	
306			ehdr := make([]byte, checkpointEntrySize)
307			for i := uint32(0); i < count; i++ {
308				if err := readFull(r, ehdr); err != nil {
309					f.Close()
310					return fail(err)
311				}
312				h.Write(ehdr)
313				flag := ehdr[0]
314				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
315				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
316				seq := binary.LittleEndian.Uint64(ehdr[9:17])
317				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
318					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
319					(flag == ckptFlagDelete && valLen != 0) {
320					f.Close()
321					return fail(errBadBackup)
322				}
323				body := make([]byte, int(keyLen)+int(valLen))
324				if err := readFull(r, body); err != nil {
325					f.Close()
326					return fail(err)
327				}
328				h.Write(body)
329				key := string(body[:keyLen])
330				// Entries must be strictly ascending and unique across segments.
331				if haveKeys && key <= lastKey {
332					f.Close()
333					return fail(errBadBackup)
334				}
335				lastKey, haveKeys = key, true
336				value := body[keyLen:]
337				if flag == ckptFlagPut {
338					if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
339						f.Close()
340						return fail(err)
341					}
342				} else {
343					if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
344						f.Close()
345						return fail(err)
346					}
347				}
348			}
349	
350			var crcb [crcSize]byte
351			if err := readFull(r, crcb[:]); err != nil {
352				f.Close()
353				return fail(err)
354			}
355			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() ||
356				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
357				f.Close()
358				return fail(errBadBackup)
359			}
360			if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
361				f.Close()
362				return fail(errBadBackup)
363			}
364			f.Close()
365			seen += uint64(count)
366		}
367	
368		if seen != info.total {
369			return fail(errBadBackup)
370		}
371		if info.snaps > 0 {
372			var v [metaValueSize]byte
373			binary.LittleEndian.PutUint64(v[:], info.snaps)
374			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
375				return fail(err)
376			}
377		}
378		if err := l.w.Flush(); err != nil {
379			return fail(err)
380		}
381		if err := wf.Sync(); err != nil {
382			return fail(err)
383		}
384		if err := wf.Close(); err != nil {
385			return err
386		}
387		return syncDirectory(stage)
388	}
389	
390	// installRestoreTarget puts the fully built staging store onto target. The
391	// target is absent or empty: when it exists as an empty directory it is
392	// removed first, so the rename lands on no existing entry. A crash in between
393	// leaves either an empty/absent target or the complete store, never a partial
394	// one.
395	func installRestoreTarget(stage, target string) error {
396		if info, err := os.Stat(target); err == nil && info.IsDir() {
397			if err := os.Remove(target); err != nil {
398				return err
399			}
400			if err := syncDirectory(filepath.Dir(target)); err != nil {
401				return err
402			}
403		}
404		if err := os.Rename(stage, target); err != nil {
405			return err
406		}
407		return syncDirectory(filepath.Dir(target))
408	}
409	
410	// sweepRestoreDebris removes a half-built temporary restore directory left
411	// next to dir by a kill during Restore. It only ever removes the specific
412	// sibling names Restore creates.
413	func sweepRestoreDebris(dir string) {
414		parent := filepath.Dir(dir)
415		base := filepath.Base(dir)
416		entries, err := os.ReadDir(parent)
417		if err != nil {
418			return
419		}
420		fixed := base + ".restore.tmp"
421		for _, e := range entries {
422			name := e.Name()
423			if !e.IsDir() {
424				continue
425			}
426			if name == fixed || isRestoreTempName(name, base) {
427				_ = os.RemoveAll(filepath.Join(parent, name))
428			}
429		}
430		_ = syncDirectory(parent)
431	}
432	
433	// isRestoreTempName matches MkdirTemp's "<base>.restore-<random>" directories.
434	func isRestoreTempName(name, base string) bool {
435		prefix := base + ".restore-"
436		return len(name) > len(prefix) && name[:len(prefix)] == prefix
437	}
438	
439	// openBackupSweep cleans incomplete-backup debris found when opening a
440	// directory that was used as a backup output: a staging directory or manifest
441	// temp is always debris, and finished segments are debris only when the
442	// manifest that completes the artifact is absent. A complete artifact is left
443	// untouched.
444	func openBackupSweep(dir string) error {
445		if err := sweepBackupDebris(dir); err != nil {
446			return err
447		}
448		if _, err := os.Stat(filepath.Join(dir, backupManifest)); err == nil {
449			return nil // complete artifact; leave it in place
450		}
451		entries, err := os.ReadDir(dir)
452		if err != nil {
453			return err
454		}
455		var names []string
456		for _, e := range entries {
457			if !e.IsDir() && isBackupSegmentName(e.Name()) {
458				names = append(names, e.Name())
459			}
460		}
461		sort.Strings(names)
462		for _, name := range names {
463			if err := os.Remove(filepath.Join(dir, name)); err != nil &&
464				!errors.Is(err, os.ErrNotExist) {
465				return err
466			}
467		}
468		if len(names) > 0 {
469			return syncDirectory(dir)
470		}
471		return nil
472	}
