1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// viewFlattenLimit bounds how deep an overlay chain a published view grows
16	// before the next commit builds it on a flattened copy. Without a bound the
17	// chain would gain one map per commit for the life of the store and memory
18	// would track cumulative commits; flattening every viewFlattenLimit commits
19	// keeps live depth (and the work a read or checkpoint walk does) independent
20	// of commit count, while the flattened copies stay immutable for every
21	// snapshot already holding an older view.
22	const viewFlattenLimit = 64
23	
24	// node is one immutable version in a key's history. Versions form a linked
25	// list from newest to oldest; a snapshot pins the head current when it was
26	// acquired, so overwritten and deleted values stay readable through every
27	// view that references them. seq is the version's commit number, unique and
28	// strictly increasing along each key's chain; it orders versions across the
29	// independent chains that meet again during a pinning compaction.
30	type node struct {
31		value   []byte
32		present bool   // false marks a delete; a present nil/empty value is still a hit
33		seq     uint64 // commit order, 1-based
34		older   *node
35	}
36	
37	// view is an immutable map of keys to their newest version. Rather than
38	// copying the whole map for every commit, a view is a thin overlay: its own
39	// keys on top of a base view it never modifies. Reads descend the short chain
40	// of overlays; the current view, snapshots and cursors simply point at one.
41	//
42	// A view's keys map may itself hold the whole keyspace: the base layer
43	// (base == nil) used by recovery, compaction and periodic flattening. Maps
44	// are never mutated after publication, so reading them needs no lock; only
45	// the commit path, which has just created a fresh overlay, writes its keys.
46	type view struct {
47		keys  map[string]*node
48		base  *view
49		depth int // number of overlays from this view to its flat base
50	}
51	
52	// newView returns an empty overlay atop base (nil for a flat base view).
53	func newView(base *view) *view {
54		d := 1
55		if base != nil {
56			d = base.depth + 1
57		}
58		return &view{keys: make(map[string]*node), base: base, depth: d}
59	}
60	
61	// lookup returns the newest version recorded for key anywhere along the
62	// overlay chain, or nil when the key was never written.
63	func (v *view) lookup(key string) *node {
64		for cur := v; cur != nil; cur = cur.base {
65			if n, ok := cur.keys[key]; ok {
66				return n
67			}
68		}
69		return nil
70	}
71	
72	// rangeEach visits the terminal version of every distinct key, fn once per
73	// key, walking newest-to-oldest so an overlay entry shadows its base.
74	func (v *view) rangeEach(fn func(key string, n *node) bool) {
75		seen := make(map[string]struct{})
76		for cur := v; cur != nil; cur = cur.base {
77			for k, n := range cur.keys {
78				if _, ok := seen[k]; ok {
79					continue
80				}
81				seen[k] = struct{}{}
82				if !fn(k, n) {
83					return
84				}
85			}
86		}
87	}
88	
89	// flatten materializes one flat map holding the view's complete terminal
90	// state. It allocates a fresh map and shares only immutable nodes, so views
91	// already published stay untouched.
92	func (v *view) flatten() *view {
93		flat := newView(nil)
94		v.rangeEach(func(k string, n *node) bool {
95			flat.keys[k] = n
96			return true
97		})
98		return flat
99	}
100	
101	// Store is an open key-value store backed by a directory on disk.
102	type Store struct {
103		mu sync.Mutex // serializes writers and guards the fields below
104	
105		dir       string
106		wal       *walWriter
107		current   atomic.Pointer[view] // latest committed view; lock-free for readers
108		snapshots atomic.Uint64        // cumulative number of snapshots handed out
109		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
110	
111		// chain is the in-memory record of the usable checkpoint layers paired
112		// with the current WAL, oldest first. Empty means no checkpoint is live
113		// (the next Checkpoint writes a base). Compaction re-anchors it against
114		// the replacement log; Checkpoint appends a delta and prunes the window.
115		chain []layerState
116		// dirty keys were touched by effective commits strictly after the newest
117		// layer in chain; they are exactly the keys the next delta layer covers.
118		// nil until the first such commit.
119		dirty []string
120		// legacyLive reports that a version-1 single-file snapshot.ckpt was the
121		// checkpoint paired with the WAL at open and has not been replaced by a
122		// layered chain or retired by compaction. Compaction must durably retire
123		// it before swapping the WAL, exactly as it retires a layered chain.
124		legacyLive bool
125	
126		// Open cursors pin their fixed view's versions against compaction. The
127		// set is read by Compact (which holds mu) and mutated at cursor
128		// open/close, using cursorMu; reads never take either lock.
129		cursorMu sync.Mutex
130		cursors  map[*Cursor]struct{}
131	
132		// Group-commit queue. Every state-changing commit (single Put/Delete just
133		// like CommitBatch) that arrives while another commit is forcing the log
134		// lines up here; one leader drains the queue, encodes the waiting commits
135		// and shares a single flush plus fsync across them.
136		// queueMu only ever guards this queue and committer; it is never held
137		// across disk I/O, so readers and enqueuers never wait on a sync.
138		queueMu   sync.Mutex
139		queue     []*pendingBatch
140		committer bool
141	
142		// Test hook, nil outside tests. leaderHook runs once after a commit has
143		// become leader, before its first queue drain, and lets tests hold a
144		// leader until a known number of commits have coalesced.
145		leaderHook func()
146	
147		closed atomic.Bool
148	}
149	
150	// Snapshot is a stable read-only view of a store captured at one instant. It
151	// owns no store resources of its own and stays usable after the store has
152	// been closed; a cursor opened from it does register with the store while it
153	// pins versions.
154	type Snapshot struct {
155		v     atomic.Pointer[view] // nil once the snapshot is closed
156		store *Store               // back-reference for cursor pin accounting
157	}
158	
159	// Open opens or creates a persistent store in dir. A path that names a
160	// regular file rather than a directory returns an error wrapping
161	// fs.ErrInvalid.
162	func Open(dir string) (*Store, error) {
163		info, err := os.Stat(dir)
164		if err == nil {
165			if !info.IsDir() {
166				return nil, errNotDir
167			}
168		} else {
169			if !errors.Is(err, fs.ErrNotExist) {
170				return nil, err
171			}
172			if err := os.MkdirAll(dir, 0o700); err != nil {
173				return nil, err
174			}
175		}
176	
177		// A replacement log from a compaction killed before its rename can never
178		// be complete state of record; the old wal.log is. Drop the stale file.
179		// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
180		// temp or a legacy single-file temp) is swept: only finished layers are
181		// ever read.
182		if err := removeStaleCompact(dir); err != nil {
183			return nil, err
184		}
185		if err := sweepCheckpointDebris(dir); err != nil {
186			return nil, err
187		}
188		if err := sweepStagedChain(dir); err != nil {
189			return nil, err
190		}
191		// Sweep debris from a hot backup that was killed before its manifest, and
192		// from a restore killed before its target rename. These names never appear
193		// in a live store, so a store that was merely backed up is unaffected.
194		if err := openBackupSweep(dir); err != nil {
195			return nil, err
196		}
197		sweepRestoreDebris(dir)
198	
199		latest := newView(nil)
200		var replaySeq uint64
201		var snapshotCount uint64
202		var validSize int64
203		var chain []layerState
204		var tailTouched []string
205		var legacyLive bool
206	
207		// apply installs one replayed record into the latest view. Legacy
208		// records (written before sequence numbers existed) carry no seq; replay
209		// order is commit order, so number them sequentially.
210		apply := func(op byte, key string, value []byte, seq uint64) {
211			if seq == 0 {
212				replaySeq++
213				seq = replaySeq
214			} else if seq > replaySeq {
215				replaySeq = seq
216			}
217			switch op {
218			case opPut, opPutSeq:
219				latest.keys[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest.keys[key]}
220			case opDelete, opDeleteSeq:
221				latest.keys[key] = &node{present: false, seq: seq, older: latest.keys[key]}
222			}
223		}
224	
225		// Fast reopen: seed memory from the longest valid checkpoint-chain prefix
226		// and replay only the WAL written after its last layer. A layer is
227		// accepted only as a whole and only when it links to the layer before; a
228		// missing, truncated, checksum-bad, unknown-version or unlinked layer
229		// rejects it and every layer after it, and recovery falls back to the
230		// previous layer, to the legacy single-file checkpoint, or finally to a
231		// from-scratch WAL replay.
232		chainInfo, chainErr := readChain(dir)
233		if chainErr != nil {
234			return nil, chainErr
235		}
236		// Reject the suffix outright: anything beyond the longest intact, linked
237		// prefix is removed as a whole so a broken layer never pairs with the WAL
238		// and never occupies space. Half a layer is never installed.
239		pruneRejectedChainFiles(dir, len(chainInfo.layers))
240		walLen, sizeErr := walFileSize(dir)
241		if sizeErr != nil {
242			return nil, sizeErr
243		}
244		// The selected layer's cut must lie inside this exact WAL. Cuts are
245		// nondecreasing along the chain, so any suffix whose cut ran past the end
246		// of the file is rejected as a whole down to the last pairable layer.
247		for len(chainInfo.layers) > 0 && chainInfo.layers[len(chainInfo.layers)-1].offset > walLen {
248			removeRejectedChainSuffix(dir, chainInfo.layers[len(chainInfo.layers)-1].index)
249			chainInfo.layers = chainInfo.layers[:len(chainInfo.layers)-1]
250		}
251	
252		switch {
253		case len(chainInfo.layers) > 0:
254			// Compose the valid prefix: each layer overrides the one it builds on.
255			var last layerState
256			for _, l := range chainInfo.layers {
257				for _, e := range l.entries {
258					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
259				}
260				last = l
261			}
262			chain = chainInfo.layers
263			replaySeq = last.seq
264			// Replay the tail, remembering touched keys so the first delta layer
265			// taken in this opening also covers commits already past the cut.
266			tailApply := func(op byte, key string, value []byte, seq uint64) {
267				if op == opPut || op == opPutSeq || op == opDelete || op == opDeleteSeq {
268					tailTouched = append(tailTouched, key)
269				}
270				apply(op, key, value, seq)
271			}
272			var rerr error
273			validSize, snapshotCount, rerr = replayWALTail(dir, last.offset, last.snaps, tailApply)
274			if rerr != nil {
275				return nil, rerr
276			}
277		default:
278			// No layered chain: accept a legacy version-1 checkpoint if one is
279			// intact and pairs with this WAL, otherwise replay the whole log.
280			cp, cpOK, cpErr := loadLegacyCheckpoint(dir)
281			if cpErr != nil {
282				removeRejectedLegacy(dir)
283				cpOK = false
284			}
285			if cpOK && (cp.offset < 0 || cp.offset > walLen) {
286				removeRejectedLegacy(dir)
287				cpOK = false
288			}
289			if cpOK {
290				legacyLive = true
291				for _, e := range cp.entries {
292					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
293				}
294				replaySeq = cp.seq
295				validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
296				if err != nil {
297					return nil, err
298				}
299			} else {
300				validSize, snapshotCount, err = replayWAL(dir, apply)
301				if err != nil {
302					return nil, err
303				}
304			}
305		}
306	
307		wal, err := openWALWriter(dir, validSize)
308		if err != nil {
309			return nil, err
310		}
311	
312		s := &Store{
313			dir:        dir,
314			wal:        wal,
315			cursors:    make(map[*Cursor]struct{}),
316			nextSeq:    replaySeq,
317			chain:      chain,
318			dirty:      dedupeKeys(nil, tailTouched),
319			legacyLive: legacyLive,
320		}
321		s.snapshots.Store(snapshotCount)
322		s.current.Store(latest)
323		return s, nil
324	}
325	
326	// dedupeKeys returns app's distinct keys appended to dst, first occurrence
327	// wins, preserving order.
328	func dedupeKeys(dst, src []string) []string {
329		seen := make(map[string]struct{}, len(src))
330		out := dst
331		for _, k := range src {
332			if _, ok := seen[k]; ok {
333				continue
334			}
335			seen[k] = struct{}{}
336			out = append(out, k)
337		}
338		return out
339	}
340	
341	// Put stores value under key. An empty key returns an error wrapping
342	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
343	// key reports a hit. The store does not keep a reference to value.
344	//
345	// Put is exactly a one-op batch: it joins the same group-commit queue as
346	// CommitBatch, so a single write and concurrent batches can share one disk
347	// sync while each keeps its own crash atomicity.
348	func (s *Store) Put(key string, value []byte) error {
349		if s.closed.Load() {
350			return errStoreClosed
351		}
352		if key == "" {
353			return errEmptyKey
354		}
355		return s.commit([]BatchOp{{Key: key, Value: value}})
356	}
357	
358	// Delete removes key. Deleting an empty key returns an error wrapping
359	// fs.ErrInvalid; deleting a key that was never written or is already deleted
360	// is not an error and commits nothing. It joins the same group-commit queue a
361	// batch uses.
362	func (s *Store) Delete(key string) error {
363		if s.closed.Load() {
364			return errStoreClosed
365		}
366		if key == "" {
367			return errEmptyKey
368		}
369		return s.commit([]BatchOp{{Key: key, Delete: true}})
370	}
371	
372	type pendingBatch struct {
373		ops  []BatchOp
374		done chan error // buffered(1); the leader delivers the commit result
375	}
376	
377	// commitPlan is one queued batch resolved against the cumulative state built
378	// up across its whole sync group.
379	type commitPlan struct {
380		view  *view // cumulative view after this batch; nil when it committed nothing
381		dirty []string
382	}
383	
384	// BatchOp is one change in a batch committed with CommitBatch. Delete false
385	// stores Value under Key (a nil or empty Value is still a hit); Delete true
386	// removes Key.
387	type BatchOp struct {
388		Key    string
389		Value  []byte
390		Delete bool
391	}
392	
393	// commit enqueues ops as one atomic framed commit and drives the leader loop.
394	// Single-key Put/Delete and CommitBatch are all this one path.
395	func (s *Store) commit(ops []BatchOp) error {
396		if s.closed.Load() {
397			return errStoreClosed
398		}
399		if err := validateBatchOps(ops); err != nil {
400			return err
401		}
402	
403		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
404	
405		// Enqueue. queueMu guards only the queue and the leader flag and is
406		// never held across disk I/O, so followers can join a group while the
407		// leader is syncing and readers never wait.
408		s.queueMu.Lock()
409		if s.closed.Load() {
410			s.queueMu.Unlock()
411			return errStoreClosed
412		}
413		s.queue = append(s.queue, me)
414		if s.committer {
415			s.queueMu.Unlock()
416			return <-me.done // the running leader will drain this batch
417		}
418		s.committer = true
419		s.queueMu.Unlock()
420	
421		// Test-only rendezvous: invoked once by the elected leader before its
422		// first queue drain. Production leaves it nil.
423		if s.leaderHook != nil {
424			s.leaderHook()
425		}
426	
427		// Leadership: drain groups until the queue is empty. Each group takes
428		// s.mu while it forces the log, which serializes it with Snapshot,
429		// Checkpoint, Compact and Close, so a group never straddles a log swap or
430		// a layer capture.
431		for {
432			s.queueMu.Lock()
433			// Resign and re-check the queue under one critical section, so a
434			// batch enqueuing in this instant either observes the still-active
435			// leader or becomes the next one; no batch can be left queued with
436			// no leader to drain it.
437			if len(s.queue) == 0 {
438				s.committer = false
439				s.queueMu.Unlock()
440				break
441			}
442			group := s.queue
443			s.queue = nil
444			s.queueMu.Unlock()
445			for p, rerr := range s.commitGroup(group) {
446				group[p].done <- rerr
447			}
448		}
449	
450		return <-me.done
451	}
452	
453	// CommitBatch applies a group of writes and deletes as one atomic commit:
454	// the whole batch becomes visible together or not at all, and snapshots and
455	// cursors fixed at any instant see either the state before the batch or the
456	// state after it, never an in-between mixture. Changes are applied in list
457	// order; a later change to the same key overrides an earlier one within the
458	// batch. Concurrent batches take effect in commit (enqueue) order, and a
459	// later committed batch's same-key change overrides an earlier one's.
460	//
461	// Batches committed concurrently (with single Put/Delete calls among them)
462	// share the disk sync: one leader drains the queue, encodes every waiting
463	// commit as its own recoverable framed commit and forces them all with one
464	// flush plus fsync, so N commits arriving together cost one sync while each
465	// stays whole on recovery; a commit that arrives while a sync is in flight
466	// rides the next one. Reads take none of these locks and are never blocked by
467	// the sync.
468	//
469	// If any change has an empty key the whole batch is rejected before it is
470	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
471	// is written and the store's state is unchanged. A delete of a key that is
472	// absent or already deleted commits nothing, exactly like Delete; a batch
473	// containing only such no-ops (or an empty slice) commits nothing and
474	// returns nil. CommitBatch on a closed store returns an error wrapping
475	// fs.ErrClosed.
476	//
477	// Each batch is forced to stable storage before its call returns and is
478	// published as one new view; a process killed mid-commit therefore reopens
479	// with the entire batch present or entirely absent. The store does not keep
480	// references to the op Value slices after return.
481	func (s *Store) CommitBatch(ops []BatchOp) error {
482		return s.commit(ops)
483	}
484	
485	// validateBatchOps checks argument-only invariants before a batch is queued.
486	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
487	func validateBatchOps(ops []BatchOp) error {
488		for i := range ops {
489			if ops[i].Key == "" {
490				return errEmptyKey
491			}
492		}
493		for i := range ops {
494			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
495				return errRecordTooLarge()
496			}
497		}
498		return nil
499	}
500	
501	func errRecordTooLarge() error { return errors.New("snapshot: record too large") }
502	
503	// commitGroup encodes and forces every queued batch with one flush and one
504	// sync, then publishes one view per effective batch in queue (commit) order.
505	// It returns one result per batch. An encoding or sync failure fails the
506	// whole group: nothing it contained is published or sequenced. The single
507	// committer calls this; s.mu is taken for the entire force, exactly as the
508	// view transitions and checkpoint watermarks need.
509	func (s *Store) commitGroup(group []*pendingBatch) []error {
510		results := make([]error, len(group))
511	
512		s.mu.Lock()
513		defer s.mu.Unlock()
514		if s.closed.Load() || s.wal == nil {
515			// Close ran between the drain and the lock; nothing can commit.
516			for i := range results {
517				results[i] = errStoreClosed
518			}
519			return results
520		}
521	
522		// Remember where the group starts so any failure can rewind the log:
523		// unacknowledged frames must not linger at EOF and reappear under a
524		// later commit or after a reopen. Nothing is buffered here (the previous
525		// group always flushed), so EOF is the exact offset.
526		groupStart, posErr := s.wal.position()
527		if posErr != nil {
528			for i := range results {
529				results[i] = posErr
530			}
531			return results
532		}
533		rollback := func(cause error) []error {
534			if err := s.wal.truncateTo(groupStart); err != nil {
535				cause = errors.Join(cause, err)
536			}
537			for i := range results {
538				results[i] = cause
539			}
540			return results
541		}
542	
543		base := s.current.Load()
544		seq := s.nextSeq
545		plans := make([]commitPlan, 0, len(group))
546		encodedAny := false
547		var groupDirty []string
548	
549		// head caches the group-cumulative terminal node of every key the queued
550		// batches touch: a nil entry means "known absent in base". It is sized by
551		// the batches' distinct keys, never by the live keyspace. The baseline
552		// flattened the whole view inside this loop every viewFlattenLimit queued
553		// batches, so a long queue behind one sync copied the live keyspace once
554		// per viewFlattenLimit batches; now each touched key walks the (already
555		// bounded) overlay chain at most once and at most one full keyspace map is
556		// built per group, after the last overlay.
557		head := make(map[string]*node)
558		resolve := func(key string) *node {
559			if n, ok := head[key]; ok {
560				return n // nil records a key known to be absent
561			}
562			n := base.lookup(key)
563			head[key] = n
564			return n
565		}
566	
567		for _, p := range group {
568			// Each batch gets its own thin immutable overlay on the previous
569			// batch's overlay, so the view it publishes is a valid point-in-time
570			// state independent of later batches, and queued batches cost memory
571			// proportional to their own ops rather than the whole live keyspace.
572			v := newView(base)
573			var changes []batchChange
574			for i := range p.ops {
575				op := &p.ops[i]
576				headNode := resolve(op.Key)
577				if op.Delete {
578					if headNode == nil || !headNode.present {
579						continue // idempotent no-op, matching the single Delete
580					}
581					seq++
582					nn := &node{present: false, seq: seq, older: headNode}
583					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
584					v.keys[op.Key] = nn
585					head[op.Key] = nn
586				} else {
587					seq++
588					value := cloneBytes(op.Value)
589					nn := &node{value: value, present: true, seq: seq, older: headNode}
590					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
591					v.keys[op.Key] = nn
592					head[op.Key] = nn
593				}
594			}
595			if len(changes) > 0 {
596				if err := s.wal.encodeBatch(changes); err != nil {
597					return rollback(err)
598				}
599				encodedAny = true
600				for i := range changes {
601					groupDirty = append(groupDirty, changes[i].key)
602				}
603			}
604			var planView *view
605			if len(changes) > 0 {
606				planView = v
607			}
608			plans = append(plans, commitPlan{view: planView})
609			base = v
610		}
611	
612		if encodedAny {
613			// One flush, one fsync for the whole group. Return means every
614			// encoded batch in it is durable as a self-contained framed commit.
615			if err := s.wal.flushSync(); err != nil {
616				return rollback(err)
617			}
618		}
619	
620		s.nextSeq = seq
621		// Publish one view per effective batch in queue order, so each batch's
622		// state becomes observable atomically as its own point-in-time view. Then,
623		// whenever the chain reached the depth bound, publish one flattened final
624		// view. That flatten builds one full keyspace map at most (after the last
625		// overlay) and keeps read depth and the next group's baseline bounded by
626		// viewFlattenLimit rather than by queue length; the baseline built one full
627		// map per viewFlattenLimit queued batches inside the loop.
628		var finalFlat *view
629		if base.depth >= viewFlattenLimit {
630			finalFlat = base.flatten()
631		}
632		for _, plan := range plans {
633			if plan.view != nil {
634				s.current.Store(plan.view)
635			}
636		}
637		if finalFlat != nil {
638			s.current.Store(finalFlat)
639		}
640		s.dirty = dedupeKeys(s.dirty, groupDirty)
641		return results
642	}
643	
644	// Get returns the latest committed value for key. Empty keys, keys never
645	// written and deleted keys are all misses: ok is false and err is nil. The
646	// returned bytes are owned by the caller.
647	func (s *Store) Get(key string) ([]byte, bool, error) {
648		if s.closed.Load() {
649			return nil, false, errStoreClosed
650		}
651		if key == "" {
652			return nil, false, nil
653		}
654		val, ok := lookupView(s.current.Load(), key)
655		return val, ok, nil
656	}
657	
658	// Compact reclaims history: values that were overwritten or deleted and are
659	// not needed by any open snapshot or cursor are dropped from memory and the
660	// write-ahead log is atomically rewritten, so the directory occupies less
661	// space than before whenever reclaimable history existed.
662	//
663	// When a checkpoint chain is live, compaction keeps the generations inside
664	// the retention window and re-anchors them against the replacement log: that
665	// log is written as one segment per surviving layer (its prefix reproducing
666	// the layer's terminal state at a fresh cut), followed by the post-window
667	// changes and the snapshot-count meta, and the rebuilt layers reference those
668	// cuts. Generations outside the window are retired together with the old
669	// chain and stop occupying space immediately.
670	//
671	// Every open snapshot keeps its exact fixed view; every open cursor keeps
672	// paging through its exact fixed sequence, and the one version per key its
673	// view shows stays in the rewritten log until the cursor closes; the next
674	// compaction then reclaims it and shrinks the directory further. A process
675	// killed at any point during compaction reopens in a complete commit state,
676	// with every successful write, deletion and the cumulative snapshot count
677	// intact; no intermediate file needs a second compaction or checkpoint to
678	// repair.
679	//
680	// Compact serializes with writes, deletes, snapshots, cursor opens, closing
681	// and other compactions (the group-commit leader and every other mutator
682	// take the same lock); concurrent or repeated calls queue and all return nil.
683	// Compacting a closed store returns an error wrapping fs.ErrClosed.
684	func (s *Store) Compact() error {
685		s.mu.Lock()
686		defer s.mu.Unlock()
687		if s.closed.Load() {
688			return errStoreClosed
689		}
690	
691		cur := s.current.Load()
692	
693		// Pinned versions, keyed by commit sequence (globally unique). The
694		// current head of every live key in the latest view is retained; each
695		// open cursor additionally pins the single head version its fixed view
696		// shows for every present key in its range. A deleted key's tombstone is
697		// retained only when a cursor still reads an older value under it, so
698		// replay links that value as the tombstone's predecessor; otherwise the
699		// key is dropped from the rewritten log altogether, as before.
700		pinned := make(map[uint64]*node)
701		keySeqs := make(map[string][]uint64)
702		cursorPins := make(map[string]bool)
703		pin := func(k string, n *node) {
704			if n == nil {
705				return
706			}
707			if _, ok := pinned[n.seq]; !ok {
708				pinned[n.seq] = n
709				keySeqs[k] = append(keySeqs[k], n.seq)
710			}
711		}
712		for _, c := range s.openCursors() {
713			for _, k := range c.keys {
714				cursorPins[k] = true
715				pin(k, c.v.lookup(k)) // exactly the version this cursor pages out
716			}
717		}
718		for k, n := range keySetOf(cur) {
719			if n.present || cursorPins[k] {
720				pin(k, n) // live head, or a tombstone shielding a pinned value
721			}
722		}
723	
724		plan := buildCompactionPlan(pinned, keySeqs)
725		snapshotCount := s.snapshots.Load()
726	
727		// The surviving window, oldest first. Layers before it are retired.
728		window := checkpointWindow
729		if window > len(s.chain) {
730			window = len(s.chain)
731		}
732		first := len(s.chain) - window
733		windowLayers := s.chain[first:]
734		hadChain := len(s.chain) > 0
735		// paired reports any checkpoint — layered chain or a legacy single file —
736		// whose cut belongs to the WAL about to be replaced. It must be withdrawn
737		// before the swap so no checkpoint is ever read against a different log.
738		paired := hadChain || s.legacyLive
739	
740		// Phase 1 (nothing live is touched yet): build and sync the complete
741		// replacement log, and when layers survive, the matching staged chain.
742		// Any failure here removes the staged files and leaves the store and the
743		// old WAL/chain exactly as they were, so committing can continue.
744		var seg *segmentedWAL
745		if !hadChain {
746			if err := buildCompactWAL(s.dir, plan.histories(), snapshotCount); err != nil {
747				return err
748			}
749		} else {
750			// Full terminal state at each window layer's watermark, composed from
751			// the complete old chain (including the generations about to retire).
752			termStates := make([][]checkpointEntry, window)
753			for w := 0; w < window; w++ {
754				termStates[w] = composeLayers(s.chain[:first+w+1])
755			}
756			seg = planSegmentedWAL(plan, windowLayers, termStates, cur)
757			if err := buildSegmentedCompactArtifacts(s.dir, seg, snapshotCount); err != nil {
758				return err
759			}
760		}
761	
762		// Phase 2: the replacement must never meet a paired checkpoint on reopen.
763		// Durably withdraw the whole layered chain and/or the legacy file while
764		// the old wal.log is still in place; a crash after this but before the
765		// rename simply replays the old log in full. Failure precedes any
766		// stateful move, so drop the staged files and leave the store untouched.
767		if paired {
768			if err := retireChain(s.dir); err != nil {
769				removeStaleCompact(s.dir)
770				removeStagedChain(s.dir)
771				return err
772			}
773			s.legacyLive = false
774		}
775		oldWAL := s.wal
776		if err := oldWAL.close(); err != nil {
777			// Staged files have not become state of record; remove them and
778			// reopen a writer on the untouched old log, so no repair-only
779			// intermediate lingers and the next commit proceeds.
780			removeStaleCompact(s.dir)
781			removeStagedChain(s.dir)
782			reopened, openErr := openWALWriter(s.dir, -1)
783			if openErr != nil {
784				return err
785			}
786			s.wal = reopened
787			return err
788		}
789		// Phase 3: atomically rename the temp over wal.log, force the directory
790		// and open a writer on the new log. If the rename never landed the old
791		// log is intact and committing continues (staged chain is dropped).
792		nextWAL, renamed, installErr := installCompactWAL(s.dir)
793		if nextWAL == nil {
794			// The rename landed but the new log cannot be opened: the directory
795			// is not in a state where further commits are safe, so mark the
796			// store closed rather than leaving a handle only another compaction
797			// could repair.
798			s.closed.Store(true)
799			s.wal = nil
800			return installErr
801		}
802		s.wal = nextWAL
803		if renamed {
804			s.current.Store(plan.freshView())
805			if hadChain {
806				// dropCheckpoint clears any in-memory and on-disk chain so the
807				// next Checkpoint starts a fresh base with no O_EXCL collision.
808				dropCheckpoint := func() {
809					s.chain = nil
810					s.dirty = nil
811					os.RemoveAll(checkpointDirPath(s.dir))
812				}
813				if window == 0 {
814					dropCheckpoint()
815					removeStagedChain(s.dir)
816				} else if err := activateStagedChain(s.dir); err != nil {
817					// The new WAL is already live; rather than leave a half
818					// installed chain, run with no live checkpoint. The next
819					// Checkpoint establishes a fresh base.
820					dropCheckpoint()
821				} else {
822					info, ierr := readChain(s.dir)
823					if ierr != nil || len(info.layers) != window {
824						dropCheckpoint()
825					} else {
826						s.chain = info.layers
827						s.dirty = seg.tailKeys
828					}
829				}
830			}
831		} else if hadChain {
832			// Rename failed; the old WAL stayed. retireChain already removed the
833			// old chain, so drop the staged replacement as well: no checkpoint
834			// pairs with this WAL. Committing continues; the next Checkpoint heals.
835			removeStagedChain(s.dir)
836			s.chain = nil
837			s.dirty = nil
838		}
839		return installErr
840	}
841	
842	// keySetOf returns the distinct keys present anywhere in the view.
843	func keySetOf(v *view) map[string]*node {
844		out := make(map[string]*node)
845		v.rangeEach(func(k string, n *node) bool {
846			out[k] = n
847			return true
848		})
849		return out
850	}
851	
852	// Checkpoint appends one self-describing, checksummed layer to the checkpoint
853	// chain so the next Open seeds memory from the longest intact layer prefix
854	// and replays only the write-ahead log written after it, instead of replaying
855	// the whole log. The first layer (the base) holds complete committed state;
856	// every later layer covers only commits after the layer it builds on.
857	// Checkpoint changes nothing visible: every committed write and deletion, the
858	// cumulative snapshot count and every open snapshot or cursor are unaffected,
859	// and reads keep hitting memory without touching disk.
860	//
861	// Producing a layer and making it live are two distinct steps: the layer is
862	// captured under the write lock, built fully under a temporary name and
863	// forced to stable storage, then atomically renamed into place and linked to
864	// the previous layer by a content hash. A kill at any instant leaves either
865	// the old complete chain or the chain extended by one complete layer; reopen
866	// observes one complete committed state, never a half layer (staging debris
867	// is swept on the next open).
868	//
869	// Only checkpointWindow newest generations are kept: appending past the
870	// window rebuilds the chain with the oldest surviving layer as a fresh full
871	// base against the unchanged WAL and deletes the retired layers immediately.
872	//
873	// Checkpoint serializes with writes, batch commits, snapshots, cursor opens,
874	// compaction and closing (it takes the same write lock), but never with
875	// lock-free reads: Get, scans, snapshot reads and cursor paging proceed while
876	// it runs. A batch stays wholly on one side of the captured cut, and history
877	// pinned by open snapshots or cursors is left untouched. On a closed store
878	// Checkpoint returns an error wrapping fs.ErrClosed.
879	func (s *Store) Checkpoint() error {
880		s.mu.Lock()
881		defer s.mu.Unlock()
882		if s.closed.Load() {
883			return errStoreClosed
884		}
885	
886		offset, err := s.wal.position()
887		if err != nil {
888			return err
889		}
890		cur := s.current.Load()
891		snaps := s.snapshots.Load()
892	
893		if len(s.chain) == 0 {
894			// First layer: full base state. This also upgrades a legacy
895			// single-file directory: the old file is removed once the base is
896			// staged, and the WAL it pairs with has not changed.
897			layer := capturedLayer{
898				index:   0,
899				entries: captureView(cur),
900				offset:  uint64(offset),
901				seq:     s.nextSeq,
902				snaps:   snaps,
903			}
904			if err := installLayer(s.dir, layer); err != nil {
905				return err
906			}
907			if err := removeLegacyCheckpoint(s.dir); err != nil {
908				return err
909			}
910			s.legacyLive = false
911		} else {
912			last := s.chain[len(s.chain)-1]
913			layer := capturedLayer{
914				index:   last.index + 1,
915				prevCRC: last.crc,
916				entries: captureDelta(cur, s.dirty),
917				offset:  uint64(offset),
918				seq:     s.nextSeq,
919				snaps:   snaps,
920			}
921			if err := installLayer(s.dir, layer); err != nil {
922				return err
923			}
924		}
925	
926		info, err := readChain(s.dir)
927		if err != nil {
928			return err
929		}
930		s.chain = info.layers
931		s.dirty = nil
932	
933		// Enforce the retention window: keep only the newest checkpointWindow
934		// layers, rebuilt as a standalone chain against the same unchanged WAL.
935		if len(s.chain) > checkpointWindow {
936			if err := s.rebaseChainToWindow(); err != nil {
937				return err
938			}
939		}
940		return nil
941	}
942	
943	// rebaseChainToWindow rebuilds the live chain so only the newest
944	// checkpointWindow layers remain: the oldest kept layer becomes a fresh full
945	// base (materialized from the complete in-memory chain) at its existing WAL
946	// cut, and the layers after it keep their delta content at their existing
947	// cuts. The WAL is not touched.
948	func (s *Store) rebaseChainToWindow() error {
949		keep := checkpointWindow
950		if keep > len(s.chain) {
951			keep = len(s.chain)
952		}
953		first := len(s.chain) - keep
954		// Materialize full terminal state at the oldest kept layer.
955		full := composeLayers(s.chain[:first+1])
956		newLayers := make([]capturedLayer, 0, keep)
957		newLayers = append(newLayers, capturedLayer{
958			index: 0, entries: full,
959			offset: uint64(s.chain[first].offset),
960			seq:    s.chain[first].seq,
961			snaps:  s.chain[first].snaps,
962		})
963		for j := first + 1; j < len(s.chain); j++ {
964			newLayers = append(newLayers, capturedLayer{
965				index:   uint32(j - first),
966				entries: s.chain[j].entries,
967				offset:  uint64(s.chain[j].offset),
968				seq:     s.chain[j].seq,
969				snaps:   s.chain[j].snaps,
970			})
971		}
972		if err := replaceCheckpointChain(s.dir, newLayers); err != nil {
973			return err
974		}
975		info, err := readChain(s.dir)
976		if err != nil {
977			return err
978		}
979		s.chain = info.layers
980		return nil
981	}
982	
983	// composeLayers returns the full terminal state after applying layers in
984	// order (each overriding the one before), sorted by key for a canonical base.
985	func composeLayers(layers []layerState) []checkpointEntry {
986		term := make(map[string]checkpointEntry)
987		for _, l := range layers {
988			for _, e := range l.entries {
989				term[e.key] = e // later layer wins; tombstones survive as tombstones
990			}
991		}
992		out := make([]checkpointEntry, 0, len(term))
993		for _, e := range term {
994			out = append(out, e)
995		}
996		sortEntries(out)
997		return out
998	}
999	
1000	// openCursors snapshots the set of currently open cursors. Cursor views and
1001	// bounds are immutable after opening, so reading their fields here needs no
1002	// per-cursor lock.
1003	func (s *Store) openCursors() []*Cursor {
1004		s.cursorMu.Lock()
1005		defer s.cursorMu.Unlock()
1006		cs := make([]*Cursor, 0, len(s.cursors))
1007		for c := range s.cursors {
1008			cs = append(cs, c)
1009		}
1010		return cs
1011	}
1012	
1013	// Snapshot acquires a stable view. It never observes writes committed after
1014	// it returns, and keeps serving that view regardless of later writes,
1015	// deletes or Store.Close, until the Snapshot itself is closed.
1016	func (s *Store) Snapshot() (*Snapshot, error) {
1017		s.mu.Lock()
1018		defer s.mu.Unlock()
1019		if s.closed.Load() {
1020			return nil, errStoreClosed
1021		}
1022		count := s.snapshots.Add(1)
1023		if err := s.wal.appendMeta(count); err != nil {
1024			s.snapshots.Add(^uint64(0))
1025			return nil, err
1026		}
1027		snap := &Snapshot{store: s}
1028		snap.v.Store(s.current.Load())
1029		return snap, nil
1030	}
1031	
1032	// Get reads key from the snapshot's fixed view. Old values overwritten or
1033	// deleted afterwards are still readable; keys created afterwards, empty
1034	// keys and keys absent or deleted when the snapshot was taken are misses. A
1035	// read from a closed snapshot is also a plain miss, never an error. The
1036	// returned bytes are owned by the caller.
1037	func (s *Snapshot) Get(key string) ([]byte, bool) {
1038		if key == "" {
1039			return nil, false
1040		}
1041		v := s.v.Load()
1042		if v == nil {
1043			return nil, false // closed snapshot
1044		}
1045		n := v.lookup(key)
1046		if n == nil || !n.present {
1047			return nil, false
1048		}
1049		return cloneBytes(n.value), true
1050	}
1051	
1052	// Close releases the snapshot's fixed view. Closing more than once is a
1053	// no-op returning nil.
1054	func (s *Snapshot) Close() error {
1055		s.v.Store(nil)
1056		return nil
1057	}
1058	
1059	// Close flushes and closes the store. Data already committed stays complete
1060	// and readable after reopening the directory. Snapshots still open keep
1061	// serving their fixed views until closed themselves; closing an already
1062	// closed store is a no-op returning nil.
1063	func (s *Store) Close() error {
1064		s.mu.Lock()
1065		if !s.closed.CompareAndSwap(false, true) {
1066			s.mu.Unlock()
1067			return nil
1068		}
1069		wal := s.wal
1070		s.wal = nil
1071		s.mu.Unlock()
1072	
1073		return wal.close()
1074	}
1075	
1076	func lookupView(v *view, key string) ([]byte, bool) {
1077		n := v.lookup(key)
1078		if n == nil || !n.present {
1079			return nil, false
1080		}
1081		return cloneBytes(n.value), true
1082	}
1083	
1084	func cloneBytes(b []byte) []byte {
1085		if b == nil {
1086			return nil
1087		}
1088		c := make([]byte, len(b))
1089		copy(c, b)
1090		return c
1091	}
1092

