73	func TestBackupRestoreRoundtrip(t *testing.T) {
74		srcDir := tempDir(t)
75		s := openStore(t, srcDir)
76		seedState(t, s)
77		for i := 0; i < 3; i++ {
78			if _, err := s.Snapshot(); err != nil {
79				t.Fatal(err)
80			}
81		}
82		want := allPairs(t, s)
83		if snaps := s.Stats().Snapshots; snaps != 3 {
84			t.Fatalf("snapshots before backup: %d, want 3", snaps)
85		}
86	
87		backupDir := filepath.Join(t.TempDir(), "backup")
88		if err := s.Backup(backupDir); err != nil {
89			t.Fatalf("Backup: %v", err)
90		}
91		// A complete artifact has a manifest and no staging directory.
92		if _, err := os.Stat(filepath.Join(backupDir, backupManifest)); err != nil {
93			t.Fatalf("manifest missing: %v", err)
94		}
95		if _, err := os.Stat(filepath.Join(backupDir, backupStageDir)); !errors.Is(err, fs.ErrNotExist) {
96			t.Fatalf("staging directory left behind: %v", err)
97		}
98	
99		target := filepath.Join(t.TempDir(), "restored")
100		rs, err := Restore(backupDir, target)
101		if err != nil {
102			t.Fatalf("Restore: %v", err)
103		}
104		// The restored store is usable immediately, without a reopen, and first
105		// shows exactly the watermark state.
106		assertSamePairs(t, allPairs(t, rs), want, "restored live state")
107		if _, ok, _ := rs.Get("gone"); ok {
108			t.Fatal("deleted key resurrected by restore")
109		}
110		if got, ok, _ := rs.Get("empty"); !ok || len(got) != 0 {
111			t.Fatalf("empty-value hit lost: ok=%v len=%d", ok, len(got))
112		}
113		if snaps := rs.Stats().Snapshots; snaps != 3 {
114			t.Fatalf("restored snapshot count: %d, want 3", snaps)
115		}
116		if err := rs.Put("after-restore", []byte("z")); err != nil {
117			t.Fatalf("put on restored store: %v", err)
118		}
119		if got, ok, _ := rs.Get("after-restore"); !ok || string(got) != "z" {
120			t.Fatalf("post-restore write missing: %q %v", got, ok)
121		}
122		if err := rs.Close(); err != nil {
123			t.Fatal(err)
124		}
125	
126		// Reopen: byte-for-byte the watermark state plus the one post-restore put,
127		// snapshot count intact and continuing.
128		s2, err := Open(target)
129		if err != nil {
130			t.Fatal(err)
131		}
132		defer s2.Close()
133		want2 := append(append([]KVPair{}, want...), KVPair{Key: "after-restore", Value: []byte("z")})
134		sort.Slice(want2, func(i, j int) bool { return want2[i].Key < want2[j].Key })
135		assertSamePairs(t, allPairs(t, s2), want2, "reopened restored state")
136		if n := s2.Stats().Snapshots; n != 3 {
137			t.Fatalf("snapshot count after reopen: %d, want 3", n)
138		}
139		if _, err := s2.Snapshot(); err != nil {
140			t.Fatal(err)
141		}
142		if n := s2.Stats().Snapshots; n != 4 {
143			t.Fatalf("snapshot count does not continue: %d, want 4", n)
144		}
145	
146		// The source store is untouched and still fully usable.
147		if got, ok, _ := s.Get("alpha"); !ok || string(got) != "one" {
148			t.Fatalf("source store changed by backup: %q %v", got, ok)
149		}
150	}
