274	func TestBackupConcurrentWithCommits(t *testing.T) {
275		s := openStore(t, tempDir(t))
276		for i := 0; i < 50; i++ {
277			if err := s.Put(fmt.Sprintf("init-%03d", i), []byte("i")); err != nil {
278				t.Fatal(err)
279			}
280		}
281	
282		var wg sync.WaitGroup
283		stop := make(chan struct{})
284		for g := 0; g < 4; g++ {
285			wg.Add(1)
286			go func(g int) {
287				defer wg.Done()
288				for i := 0; ; i++ {
289					select {
290					case <-stop:
291						return
292					default:
293					}
294					if err := s.CommitBatch([]BatchOp{
295						{Key: fmt.Sprintf("w%d-%05d", g, i), Value: []byte(fmt.Sprintf("%d", i))},
296						{Key: "shared", Value: []byte(fmt.Sprintf("%d-%d", g, i))},
297					}); err != nil {
298						return
299					}
300				}
301			}(g)
302		}
303	
304		// Several backups run while writes flow; each must succeed and restore to
305		// a self-consistent state, and the reads never block on the export.
306		var backups []string
307		deadline := time.Now().Add(3 * time.Second)
308		for time.Now().Before(deadline) {
309			bd := filepath.Join(t.TempDir(), "backup")
310			if err := s.Backup(bd); err != nil {
311				close(stop)
312				wg.Wait()
313				t.Fatalf("concurrent Backup: %v", err)
314			}
315			backups = append(backups, bd)
316		}
317		close(stop)
318		wg.Wait()
319	
320		for _, bd := range backups {
321			rs, err := Restore(bd, filepath.Join(t.TempDir(), "r"))
322			if err != nil {
323				t.Fatalf("restore concurrent backup: %v", err)
324			}
325			pairs := allPairs(t, rs)
326			// Restored state must be internally consistent: unique sorted keys and
327			// every value decodes as a non-negative decimal "g-i" marker for the
328			// shared key and init keys present.
329			for i := 1; i < len(pairs); i++ {
330				if pairs[i].Key <= pairs[i-1].Key {
331					t.Fatalf("restored pairs not strictly ordered at %d", i)
332				}
333			}
334			if _, ok, _ := rs.Get("shared"); !ok {
335				t.Fatal("shared key missing in restored backup")
336			}
337			if _, ok, _ := rs.Get("init-000"); !ok {
338				t.Fatal("pre-backup key missing in restored backup")
339			}
340			rs.Close()
341		}
342	}
