735	// TestQueuedBatchMemoryDoesNotScaleWithLiveKeys guards the group-commit
736	// tightening: a long queue coalescing behind one sync against a thousand-key
737	// store must publish correct state and leave the committed view shallow; the
738	// temporary maps it builds never scale with the queue length.
739	func TestQueuedBatchMemoryDoesNotScaleWithLiveKeys(t *testing.T) {
740		s := openStore(t, tempDir(t))
741		const liveKeys = 1500
742		seed := make([]BatchOp, liveKeys)
743		for i := range seed {
744			seed[i] = BatchOp{Key: fmt.Sprintf("live-%05d", i), Value: []byte("payload")}
745		}
746		if err := s.CommitBatch(seed); err != nil {
747			t.Fatal(err)
748		}
749	
750		probe := func() {
751			const followers = 200
752			proceed := make(chan struct{})
753			var leaderWG sync.WaitGroup
754			leaderWG.Add(1)
755			s.leaderHook = func() {
756				leaderWG.Done()
757				<-proceed
758			}
759			leaderErr := make(chan error, 1)
760			go func() {
761				leaderErr <- s.CommitBatch([]BatchOp{{Key: "leader", Value: []byte("L")}})
762			}()
763			leaderWG.Wait()
764	
765			var wg sync.WaitGroup
766			for i := 0; i < followers; i++ {
767				wg.Add(1)
768				go func(i int) {
769					defer wg.Done()
770					if err := s.CommitBatch([]BatchOp{{Key: fmt.Sprintf("q-%04d", i), Value: []byte("x")}}); err != nil {
771						t.Errorf("follower %d: %v", i, err)
772					}
773				}(i)
774			}
775			for queueLen(s) != followers+1 {
776				runtime.Gosched()
777			}
778			close(proceed)
779			if err := <-leaderErr; err != nil {
780				t.Errorf("leader: %v", err)
781			}
782			wg.Wait()
783			s.leaderHook = nil
784		}
785	
786		// Repeated queueing must not accumulate overlay depth or stale maps.
787		for round := 0; round < 4; round++ {
788			probe()
789			if d := s.current.Load().depth; d > viewFlattenLimit {
790				t.Fatalf("round %d: post-group view depth %d exceeds %d", round, d, viewFlattenLimit)
791			}
792			runtime.GC()
793		}
794	
795		if got, ok, _ := s.Get("live-00000"); !ok || string(got) != "payload" {
796			t.Fatalf("live state wrong after queued groups: %q %v", got, ok)
797		}
798		if got, ok, _ := s.Get("q-0199"); !ok || string(got) != "x" {
799			t.Fatalf("queued write missing: %q %v", got, ok)
800		}
801		if st := s.Stats(); st.Keys != liveKeys+200+1 {
802			t.Fatalf("keys after queued groups: %d, want %d", st.Keys, liveKeys+201)
803		}
804	
805		// The retained state must reopen intact.
806		dir := s.dir
807		if err := s.Close(); err != nil {
808			t.Fatal(err)
809		}
810		s2, err := Open(dir)
811		if err != nil {
812			t.Fatal(err)
813		}
814		defer s2.Close()
815		if st := s2.Stats(); st.Keys != liveKeys+200+1 {
816			t.Fatalf("keys after reopen: %d, want %d", st.Keys, liveKeys+201)
817		}
818	}
