		t.Fatalf("Backup: %v", err)
	}
	entries, err := os.ReadDir(backupDir)
	if err != nil {
		t.Fatal(err)
	}
	var nSeg int
	for _, e := range entries {
		if isBackupSegmentName(e.Name()) {
			nSeg++
		}
	}
	if nSeg != 3 {
		t.Fatalf("segment count = %d, want 3", nSeg)
	}

