		{Key: "c", Value: []byte("c1")},
		{Key: "c", Delete: true}, // put-then-delete within view across commits
		{Key: "d", Delete: true},
		{Key: "d", Value: []byte("d1")}, // delete-then-put
	}); err != nil {
		t.Fatal(err)
	}
