mergeHeap:

```go
// mergeItem is one link's current entry in the synthesis merge.
type mergeItem struct {
	entry  backupEntry
	stream *ringStream
	ring   int // chain position; higher overrides lower for the same key
}

// mergeHeap orders current entries by key, breaking ties toward the newest
// link so the chain's last word on a key pops first.
type mergeHeap []mergeItem

func (h mergeHeap) Len() int { return len(h) }
func (h mergeHeap) Less(i, j int) bool {
	if h[i].entry.key != h[j].entry.key {
		return h[i].entry.key < h[j].entry.key
	}
	return h[i].ring > h[j].ring
}
func (h mergeHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *mergeHeap) Push(x any)        { *h = append(*h, x.(mergeItem)) }
func (h *mergeHeap) Pop() any {
	old := *h
	n := len(old)
	it := old[n-1]
	*h = old[:n-1]
	return it
}
```

