```go
// advance moves the stream to its next entry. It returns false when the link
// is exhausted; a exhausted link whose entry total disagrees with its
// manifest is an error.
func (s *ringStream) advance() (bool, error) {
	for {
		if s.open && s.left == 0 {
			if err := s.finishSegment(); err != nil {
				return false, err
			}
			s.open = false
		}
		if !s.open {
			if s.seg >= len(s.info.segments) {
				if s.seen != s.info.total {
					return false, errBadBackup
				}
				return false, nil
			}
			if err := s.openSegment(); err != nil {
				return false, err
			}
		}
		e, err := s.readEntry()
		if err != nil {
			return false, err
		}
		s.left--
		s.seen++
		s.cur = e
		return true, nil
	}
}
