		binary.LittleEndian.Uint64(hdr[8:16]) != s.info.watermark ||
		binary.LittleEndian.Uint64(hdr[16:24]) != s.info.snaps ||
		binary.LittleEndian.Uint32(hdr[24:28]) != seg.index ||
		binary.LittleEndian.Uint32(hdr[28:32]) != seg.count ||
